using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using ProjectionMapper.Models;
using ProjectionMapper.Utilities;

// Explicit synthetic coordinates/image for mathematical and persistence contracts, not a photograph of a real installation.
internal static class CameraFixture
{
    public const string Jpeg = "";
    public static readonly double[] Transform = { 1.2, .1, -.12, .04, 1.05, -.08, .08, -.03, 1 };
    public static CameraPattern Pattern()
    {
        var pattern = new CameraPattern { Width = 1280, Height = 960, Region = new(0, 0, 1280, 960) };
        for (int i = 0; i < 9; i++) pattern.Markers.Add(new(i + 10, (int)Math.Round(1280 * (.08 + .42 * (i % 3)) - 31.5), (int)Math.Round(960 * (.08 + .42 * (i / 3)) - 31.5), 64, i is 1 or 3 or 5));
        return pattern;
    }
    public static List<MarkerObservation> Matches(CameraPattern pattern)
    {
        var inverse = PlanarCalibration.Inverse(Transform);
        return pattern.Markers.Select(m => new MarkerObservation { Id = m.Id, Photo = PlanarCalibration.Transform(inverse, new(m.Center.X / pattern.Width, m.Center.Y / pattern.Height)), ValidationOnly = m.ValidationOnly, Origin = "Manual" }).ToList();
    }
    public static CameraCalibrationRecord Record()
    {
        var pattern = Pattern(); var matches = Matches(pattern); var fit = PlanarCalibration.Fit(pattern, matches, 3);
        var inverse = PlanarCalibration.Inverse(Transform);
        var target = new[] { new PhotoPoint(.3, .3), new(.7, .3), new(.7, .7), new(.3, .7) }.Select(p => PlanarCalibration.Transform(inverse, p)).ToList();
        var quad = PlanarCalibration.MapTarget(pattern, matches, fit, target, false);
        return new() { MeshId = "fixture-mesh", MeshName = "Synthetic plane", ComputerId = "fixture-computer", Output = new(0, "fixture-display", "fixture-id", 0, 0, 1280, 960, 1280, 960, true),
            Pattern = pattern, Matches = matches, Photo = new() { Width = 640, Height = 480, OriginalFileName = "synthetic-blank.jpg", ImageBase64 = Jpeg, ImageSha256 = Convert.ToHexString(SHA256.HashData(Convert.FromBase64String(Jpeg))) },
            PhotoToProjector = fit.Matrix, FitRmsPixels = fit.FitRmsPixels, ValidationRmsPixels = fit.ValidationRmsPixels, ValidationMaxPixels = fit.ValidationMaxPixels,
            TolerancePixels = 3, OperatorConfirmed = true, TargetPhotoCorners = target, OutputCorners = quad.SelectMany(p => new[] { p.X, p.Y }).ToArray() };
    }
}
